VARIANTS: List[str] = ["en", "hi", HINGLISH, "gu", "pa", "mr", "bn", "ta", "te", "kn", "ml", "or"]


def text(purpose: str, variant: str) -> str:
    """The nudge for a purpose in a language variant, English when it has none."""
    by = TEXT[purpose]
    return by.get(variant) or by["en"]


def variant_for(lang: Optional[str], latin_hindi: bool) -> str:
    """The variant for a language: Hinglish for Hindi written in Latin letters."""
    if lang == "hi" and latin_hindi:
        return HINGLISH
    return lang if lang in TEXT["more_info"] else "en"
